document.querySelectorAll('[data-lab="CP02-I1"]').forEach(root=>{
const z=root.dataset.lang==='zh',f=k=>root.querySelector('[data-field="'+k+'"]');let seed=123456;
const txt=(x,y,s,size=22)=>'<text x="'+x+'" y="'+y+'" font-size="'+size+'">'+s+'</text>';
const line=(x,y,X,Y,c='#8ba1a3')=>'<line x1="'+x+'" y1="'+y+'" x2="'+X+'" y2="'+Y+'" stroke="'+c+'" stroke-width="2"/>';
const path=(p,c,w=3)=>'<path d="'+p.map((v,i)=>(i?'L':'M')+v[0].toFixed(2)+','+v[1].toFixed(2)).join(' ')+'" fill="none" stroke="'+c+'" stroke-width="'+w+'"/>';
function draw(){let delta=+f('gap').value,B=+f('barrier').value,initial=+f('initial').value,T=+f('time').value,ab=Math.exp(-B-Math.max(delta,0)),ba=Math.exp(-B-Math.max(-delta,0)),peq=ab/(ab+ba),tau=1/(ab+ba);f('dv').textContent=delta.toFixed(2);f('bv').textContent=B.toFixed(2);f('tv').textContent=T;
let rng=seed>>>0;function random(){rng=(Math.imul(rng,1664525)+1013904223)>>>0;return(rng+.5)/4294967296;}
let events=[{t:0,s:initial}],t=0,state=initial;while(events.length<5000){t+=-Math.log(random())/(state?ba:ab);if(t>200)break;state=1-state;events.push({t,s:state});}
function obs(until){let occupied=0,current=initial,jumps=0;for(let i=0;i<events.length;i++){let start=events[i].t;if(start>until)break;let end=Math.min(until,i+1<events.length?events[i+1].t:200);occupied+=(end-start)*events[i].s;current=events[i].s;if(i)jumps++;}return{average:until?occupied/until:null,current,jumps};}
const ensemble=time=>peq+(initial-peq)*Math.exp(-time/tau),X=time=>65+time*2.4,Y=s=>285-s*140;let p=[],s='<g font-family="Arial,sans-serif" fill="#173e45">'+txt(30,38,z?'单次状态记录':'One state trajectory',25);for(let i=0;i<events.length;i++){let end=i+1<events.length?events[i+1].t:200;p.push([X(events[i].t),Y(events[i].s)],[X(end),Y(events[i].s)]);}s+=line(65,315,555,315)+line(65,100,65,315)+path(p,'#207d80',3)+txt(25,Y(0)+8,'A')+txt(25,Y(1)+8,'B')+line(X(T),100,X(T),315,'#bb6a38');for(let v of [0,50,100,150,200])s+=txt(X(v)-10,355,''+v,21);s+=txt(485,390,'t / s',22);
const V=v=>730-250*v;s+=txt(30,435,z?'概率与累计时间占据':'Probability and cumulative occupation',23)+line(65,730,555,730)+line(65,470,65,730)+'<line x1="65" y1="'+V(peq)+'" x2="545" y2="'+V(peq)+'" stroke="#83989b" stroke-width="2" stroke-dasharray="8 6"/>';
s+=path(Array.from({length:201},(_,i)=>[X(i),V(ensemble(i))]),'#207d80',4)+path(Array.from({length:200},(_,i)=>[X(i+1),V(obs(i+1).average)]),'#bb6a38',3)+line(X(T),470,X(T),730,'#667c85');for(let v of [0,.5,1])s+=txt(12,V(v)+7,''+v,21);for(let v of [0,100,200])s+=txt(X(v)-10,770,''+v,21);s+=txt(490,805,'t / s',22)+'</g>';f('plot').innerHTML=s;
let result=obs(T),av=result.average===null?(z?'未定义':'undefined'):result.average.toFixed(4);f('feedback').textContent=z?'平衡B概率 '+peq.toFixed(4)+'，松弛时间 '+tau.toFixed(3)+' s。观察 '+T+' s 后：系综B概率 '+ensemble(T).toFixed(4)+'，单次累计B比例 '+av+'，当前状态 '+(result.current?'B':'A')+'，已跳转 '+result.jumps+' 次。':'Equilibrium B probability '+peq.toFixed(4)+', relaxation time '+tau.toFixed(3)+' s. At '+T+' s: ensemble B probability '+ensemble(T).toFixed(4)+', single-record B fraction '+av+', current state '+(result.current?'B':'A')+', jumps '+result.jumps+'.';}
['gap','barrier','time'].forEach(k=>f(k).addEventListener('input',draw));f('initial').addEventListener('change',draw);f('renew').addEventListener('click',()=>{seed=(seed+104729)>>>0;draw();});f('reset').addEventListener('click',()=>{f('gap').value=1;f('barrier').value=2;f('initial').value=0;f('time').value=50;seed=123456;draw();});draw();
});
